package com.example.sigla

import org.junit.Assert.assertEquals
import org.junit.Test
import kotlin.math.abs

/**
 * Parity regression guard: the Kotlin feature normalization must stay
 * byte-identical to sigla-ml preprocessor.normalize_frame.
 *
 * Expected values were generated by running the Python normalize_frame on the
 * fixture inputs (scratch script gen_parity_fixtures.py, rng seed 7). If this
 * test fails after a change to normalizeHandBlock/normalizePoseBlock, the
 * Python and Kotlin pipelines have diverged -- fix the divergence, do NOT
 * regenerate the fixtures to make the test pass, unless the SAME change was
 * deliberately made on the Python side too (which also requires a retrain).
 */
class FeatureParityTest {

    // Calls the PRODUCTION normalizeFrame — the same function parseResult() uses.
    // This used to be a test-local reimplementation of the per-hand presence rule,
    // which meant the test could pass while the real path regressed.
    private fun normalizeLikePython(frame: FloatArray): FloatArray {
        val out = frame.copyOf()
        normalizeFrame(out)
        return out
    }

    private fun check(input: FloatArray, expected: FloatArray) {
        val actual = normalizeLikePython(input)
        assertEquals(expected.size, actual.size)
        for (i in actual.indices) {
            // Relative + absolute tolerance: Python computes intermediates in
            // float64, Kotlin in float32; a real divergence is orders larger.
            val tol = maxOf(2e-5f, abs(expected[i]) * 1e-4f)
            if (abs(actual[i] - expected[i]) > tol) {
                throw AssertionError(
                    "index " + i + ": expected " + expected[i] + " got " + actual[i]
                )
            }
        }
    }

